import java.security.KeyFactory;
import java.util.Base64;
import java.security.PrivateKey;
import java.security.spec.PKCS8EncodedKeySpec;
import javax.crypto.Cipher;

public class AsymmetricDecrypt {
    public static PrivateKey getPrivateKey(String base64PrivateKey) throws Exception {
        byte[] keyBytes = Base64.getDecoder().decode(base64PrivateKey);
        PKCS8EncodedKeySpec keySpec = new PKCS8EncodedKeySpec(keyBytes);
        KeyFactory keyFactory = KeyFactory.getInstance("RSA");
        return keyFactory.generatePrivate(keySpec);
    }

    public static byte[] decryptSymmetricKey(String encryptedSymmetricKey, PrivateKey privateKey) throws Exception {
        byte[] encryptedKeyBytes = Base64.getDecoder().decode(encryptedSymmetricKey);
        Cipher cipher = Cipher.getInstance("RSA/ECB/PKCS1Padding");
        cipher.init(Cipher.DECRYPT_MODE, privateKey);
        return cipher.doFinal(encryptedKeyBytes);
    }

    public static void main(String[] args) throws Exception {
        String base64PrivateKey = "";

        String encryptedSymmetricKey = "";

        PrivateKey privateKey = getPrivateKey(base64PrivateKey);
        byte[] symmetricKey = decryptSymmetricKey(encryptedSymmetricKey, privateKey);
        System.out.println("Decrypted Symmetric Key: " + Base64.getEncoder().encodeToString(symmetricKey));
    }
}


